OrcaSlicer bug in a feature branch: the sidebar's filament-sync button now opens a small hover menu (code below). On macOS the menu appears and then disappears before the user can click either item — moving the mouse from the button down into the menu closes it, and sometimes it closes while the cursor is already over it. It works on Windows. Find the causes and fix the code.

```cpp
// Widgets/FilamentSyncMenu.hpp/.cpp (new, opened when the cursor enters the sidebar's sync button)
class FilamentSyncMenu : public PopupWindow
{
public:
    explicit FilamentSyncMenu(wxWindow* parent) : PopupWindow(parent, wxBORDER_NONE)
    {
        auto* sizer = new wxBoxSizer(wxVERTICAL);
        auto* colours = new Button(this, _L("Sync colours only"));
        auto* all     = new Button(this, _L("Sync colours and types"));
        colours->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { Dismiss(); wxGetApp().sidebar().sync_ams_list(); });
        all->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { Dismiss(); wxGetApp().sidebar().sync_ams_list(true); });
        sizer->Add(colours, 0, wxEXPAND | wxALL, FromDIP(4));
        sizer->Add(all, 0, wxEXPAND | wxALL, FromDIP(4));
        SetSizerAndFit(sizer);

        m_timer.SetOwner(this);
        Bind(wxEVT_TIMER, [this](wxTimerEvent&) { Dismiss(); });
        Bind(wxEVT_LEAVE_WINDOW, [this](wxMouseEvent&) { m_timer.StartOnce(300); });
        Bind(wxEVT_ENTER_WINDOW, [this](wxMouseEvent&) { m_timer.Stop(); });
    }

    void popup_under(wxWindow* btn)
    {
        wxPoint pos = btn->ClientToScreen(wxPoint(0, 0));
        Position(pos, {0, btn->GetSize().y + FromDIP(6)});
        Popup();
    }

private:
    wxTimer m_timer;
};

// Sidebar constructor:
m_sync_menu = new FilamentSyncMenu(ams_btn);
ams_btn->Bind(wxEVT_ENTER_WINDOW, [this](wxMouseEvent& e) { m_sync_menu->popup_under(ams_btn); e.Skip(); });
```
